export function getPairKey(teamA, teamB) {
  return [teamA, teamB]
    .sort((a, b) => TEAMS.indexOf(a) - TEAMS.indexOf(b))
    .join('|');
}

export function getAnswers(teamA, teamB) {
  return ANSWER_INDEX[getPairKey(teamA, teamB)] || [];
}
